-- Node: vafei-start (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Video-Assisted Flexible Endoscopic Intubation — Overview","body":"**Video-Assisted Flexible Endoscopic Intubation** combines video laryngoscopy to expose the airway with flexible endoscopy to guide tube delivery. [1]\n\n**WHY THIS TECHNIQUE?**\nCombines the best of both:\n• VL clears path through mouth, lifts epiglottis\n• FE provides continuous visualization through cords\n• No nasal route needed (avoids epistaxis)\n• Allows awake/breathing approach\n\n**KEY ADVANTAGES:**\n• Maintains spontaneous ventilation\n• Continuous visualization during tube passage\n• Two operators = two sets of eyes\n• Works when VL alone fails to pass tube\n\n**SUCCESS RATES:**\n• Awake flexible endoscopic intubation: 92% first-pass (nasal), 57% (oral) [3]\n• Combined video + flexible endoscopic technique addresses oral route challenges by using VL to guide the scope","citation":[1,2,3],"next":"vafei-indications","summary":"Video laryngoscopy + flexible endoscope combined; VL clears path, FE guides tube through cords; maintains breathing"}'::jsonb
WHERE id = 'vafei-start' AND tree_id = 'vafei';

-- Node: vafei-indications (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Indications","body":"**PRIMARY INDICATIONS:** [2,6,7]\n\n**Anatomically Difficult/Distorted Airways:**\n• Angioedema (most common indication)\n• Ludwig angina / deep neck infection\n• Oropharyngeal abscess / hematoma\n• Laryngeal or orofacial trauma\n• Airway tumors / masses\n• Prior surgery or radiation to head/neck\n\n**Intrinsic Difficult Airway Features:**\n• Micrognathia / retrognathia\n• Limited mouth opening (trismus)\n• Morbid obesity\n• Failed 3-3-2 rule\n• Mallampati IV\n• History of difficult intubation\n\n**Clinical Scenarios:**\n• \"Scared to paralyze\" - anticipated CICO risk\n• Failed VL intubation (can oxygenate)\n• Cervical spine immobility + predicted difficult airway\n• Need for continuous visualization (laryngeal trauma)","citation":[2,6,7],"next":"vafei-contraindications","summary":"Angioedema, Ludwig, trauma, tumors, morbid obesity, failed VL, \"scared to paralyze\" patients"}'::jsonb
WHERE id = 'vafei-indications' AND tree_id = 'vafei';

