-- Node: vafei-prep-awake (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Preparation — Awake Approach","body":"**AWAKE PREPARATION:** [1,3,7]\n\n**Equipment Setup:**\n• Video laryngoscope (hyperangulated preferred)\n• Flexible endoscope with ETT preloaded\n• Suction x2 (VL operator + backup)\n• Topical anesthetics (4% lidocaine)\n• Antisialagogue (glycopyrrolate)\n• Low-dose ketamine + midazolam drawn\n• Standard airway backup + cricothyrotomy kit\n\n**Operator Positioning:**\n• **VL Operator:** Behind patient''s LEFT shoulder\n• **FE Operator:** Behind patient''s HEAD\n• **Patient:** Semi-Fowler position (30-45°)\n• **Monitor:** Single split-screen over patient''s bed\n\n**Patient Preparation:**\n• Explain procedure, set expectations\n• Preoxygenate (HFNC ideal if available)\n• Hemodynamic optimization\n• IV access confirmed","citation":[1,3,7],"next":"vafei-antisialagogue","summary":"VL operator at left shoulder, FE operator at head; patient semi-Fowler; split-screen monitor"}'::jsonb
WHERE id = 'vafei-prep-awake' AND tree_id = 'vafei';

-- Node: vafei-prep-rsi (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Preparation — RSI Rescue","body":"**RSI-THEN-FLEXIBLE-ENDOSCOPE (RESCUE SCENARIO):** [1]\n\nWhen standard VL intubation fails but patient is oxygenating:\n\n**Setup (should already be ready):**\n• VL in place with view obtained\n• Flexible endoscope preloaded with ETT\n• Second operator available\n\n**Transition to combined technique:**\n1. VL operator maintains laryngeal view\n2. FE operator brings scope to bedside\n3. No additional meds needed (already paralyzed)\n4. Proceed directly to scope insertion\n\n**KEY POINT:**\nHaving FE available and preloaded BEFORE RSI allows immediate rescue if VL alone fails.\n\n**Time Considerations:**\n• Apnea time limited\n• May need BVM ventilation between attempts\n• Consider supraglottic rescue if prolonged","citation":[1],"next":"vafei-procedure","summary":"For RSI rescue: VL maintains view, FE operator brings scope, proceed directly; have FE ready pre-RSI"}'::jsonb
WHERE id = 'vafei-prep-rsi' AND tree_id = 'vafei';

-- Node: vafei-kobi (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Ketamine-Only Breathing Intubation (KOBI)","body":"**KOBI APPROACH:** [4,5]\n\nDissociative-dose ketamine WITHOUT paralytic. Patient breathes throughout.\n\n**INDICATIONS:**\n• Distorted airway where paralysis is dangerous\n• Need to maintain spontaneous ventilation\n• Alternative to awake approach in uncooperative patient\n\n**KETAMINE DOSING:**\n• **Dissociative:** 1-2 mg/kg IV\n• **Titration method:** 25 mg aliquots q15 seconds until dissociated\n• Have RSI backup ready\n\n**CRITICAL SAFETY:**\n• **ALWAYS have paralytic drawn and ready**\n• Laryngospasm can occur\n• Increased muscle tone may impair laryngoscopy\n• Patient may gag, cough, adduct cords\n\n**PROCEED TO PROCEDURE:**\nOnce dissociated, perform video-assisted flexible endoscopic intubation as described.\nTopical lidocaine still helpful to reduce cord reactivity.","citation":[4,5],"next":"vafei-procedure","summary":"Ketamine 1-2 mg/kg or 25mg aliquots; maintains breathing; MUST have paralytic ready for laryngospasm"}'::jsonb
WHERE id = 'vafei-kobi' AND tree_id = 'vafei';

-- Node: vafei-procedure (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Procedure — Step by Step","body":"**THE TECHNIQUE:** [1]\n\n**STEP 1: VL INSERTION**\n• VL operator inserts blade, obtains laryngeal view\n• Maintains position with LEFT hand\n• Keeps suction ready in RIGHT hand\n• \"Sets the table\" for FE operator\n\n**STEP 2: FE INSERTION**\n• FE operator looks INTO patient''s mouth (direct vision)\n• Advances scope to tip of VL blade under direct view\n• Then looks at VL SCREEN to guide scope to cords\n\n**STEP 3: CORD PASSAGE**\n• Spray lidocaine on cords via FE channel (if awake)\n• Advance FE through vocal cords\n• Use VL screen OR FE screen (whichever view is better)\n• Continue until CARINA is visualized\n\n**STEP 4: TUBE DELIVERY**\n• FE operator holds scope steady\n• Assistant (or VL operator) railroads ETT over scope\n• Advance until ETT tip visible on FE screen\n• Position just proximal to carina\n\n**KEY PEARL:**\n\"The right speed is SLOWER than your instincts.\" [1]","citation":[1],"next":"vafei-railroad","images":[{"src":"images/vafei/vafei-positioning.png","alt":"Operator positioning: VL operator at left shoulder, FE operator at head, patient semi-Fowler","caption":"Positioning: VL operator at left shoulder, FE operator behind head, patient semi-Fowler, split-screen monitor above."}],"summary":"VL obtains view → FE advances to blade tip → guides through cords on VL screen → carina → railroad ETT"}'::jsonb
WHERE id = 'vafei-procedure' AND tree_id = 'vafei';

